import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    // A stable id so the installed app keeps its identity across hosts (e.g. a dev tunnel).
    id: "/",
    name: "Yuyu",
    short_name: "Yuyu",
    description: "Create, manage, register for, and check in to free community events.",
    start_url: "/dashboard",
    scope: "/",
    display: "standalone",
    background_color: "#FFFFFF",
    theme_color: "#18181B",
    // Yuyu dot sign (public/brand, generated by scripts/generate-brand-assets.ts).
    icons: [
      { src: "/brand/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/brand/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
